select t3.area_id as provinceId,t3.area_name as province,t2.area_id as cityId,t2.area_name as city,t1.area_id as districtId ,t1.area_name as district from (select area_id,area_name,parent_id from common_area where area_id in
#{item}
and area_type =3) t1 left join (select area_id,area_name,parent_id from common_area where area_id in
#{item}
and area_type =2) t2 on t1.parent_id=t2.area_id left join (select area_id,area_name,parent_id from common_area where area_id in
#{item}
and area_type =1) t3 on t2.parent_id=t3.area_id

